assert("String");
assert("Nullable`1");
assert("Type");
assert("Array");
assert("Attribute");
assert("Object");
assert("NotSupportedException");
assert("Void");

assert("other", "default");
assert(null, "default");
assert("", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        return value switch
        {
            "String" => "String",
            "Nullable`1" => "Nullable`1",
            "Type" => "Type",
            "Array" => "Array",
            "Attribute" => "Attribute",
            "Object" => "Object",
            "NotSupportedException" => "NotSupportedException",
            "Void" => "Void",
            _ => "default"
        };
    }
}
